public int uniquePaths(int m, int n) {
    int k = Math.min(m - 1, n - 1);
    int big = (m - 1) + (n - 1) - k; // the larger of m-1, n-1
    long result = 1;
    for (int i = 1; i <= k; i++) {
        result = result * (big + i) / i;
    }
    return (int) result;
}

